// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { mergeResourceNodes, mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples, compactTerm } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import { sparqlNodeId } from "../../../main/frontend/graph-explorer/rdf-terms.ts";

const uri = (value) => ({ type: "uri", value });

// "Add to graph" on the Types page draws the class as a card of its own: no instances, no statements, no links.
test("a resource added as a node is one card without statements", () => {
  const empty = { nodes: [], edges: [], revision: 4 };
  const added = mergeResourceNodes(empty, [uri("http://example.org/Person")]);

  assert.equal(added.edges.length, 0);
  assert.equal(added.revision, 5);
  assert.deepEqual(
    added.nodes.map(({ x: _x, y: _y, ...node }) => node),
    [{
      id: "http://example.org/Person",
      termValue: "http://example.org/Person",
      label: compactTerm("http://example.org/Person"),
      labelInput: null,
      kind: "iri",
    }],
  );
  assert.ok(Number.isFinite(added.nodes[0].x) && Number.isFinite(added.nodes[0].y), "the card has a place to start from");
});

test("nodes already in the graph, repeated terms and values add nothing", () => {
  const graph = mergeTriples(
    { nodes: [], edges: [], revision: 0 },
    bindingsToTriples([{ source: uri("urn:a"), predicate: uri("urn:p"), target: uri("urn:Type") }]),
  );

  assert.equal(mergeResourceNodes(graph, [uri("urn:Type"), uri("urn:a")]), graph, "the same graph: nothing new");
  assert.equal(mergeResourceNodes(graph, [{ type: "literal", value: "urn:Type" }]), graph, "a value is no resource");

  const added = mergeResourceNodes(graph, [uri("urn:Other"), uri("urn:Other"), uri("urn:a")]);
  assert.deepEqual(added.nodes.map((node) => node.id), ["urn:a", "urn:Type", "urn:Other"]);
  assert.equal(added.edges, graph.edges, "the statements stay as they are");
  assert.equal(added.nodes[0], graph.nodes[0], "existing cards stay as they are");
});

test("a fixed blank node reference becomes a blank card under its graph id", () => {
  const reference = { type: "bnode", value: "b1", "rdf4j:reference": true };
  const added = mergeResourceNodes({ nodes: [], edges: [], revision: 0 }, [reference]);

  assert.deepEqual(added.nodes.map((node) => [node.id, node.kind, node.termValue]), [[sparqlNodeId(reference), "blank", "b1"]]);
});
